    edge = 4.0f;
    u0 = 0.1f;
    u1 = 0.89999998f;
    x += 4.0f;
    y += 3.0f;
    width -= 8.0f;
    height -= 6.0f;
} else if (current_padding < render_inset_base) {
    float delta = render_inset_base - current_padding;
    render_inset_delta = delta;
    edge = render_inset_base;
    x += delta;
    y += delta;
    width -= delta + delta;
    height -= delta + delta;
    u0 = edge * 0.0078125f;
    u1 = 1.0f - u0;
} else {
    edge = current_padding;
    u0 = 0.2f;
    u1 = 0.80000001f;
}

